window.docContents[221].resolve({"/Gamma-Function/___5___2-Definitions/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___2-Definitions--___5___2_LPAR_ii_RPAR_-Euler___s-Constant":{"contents":"\\gamma=\\lim_{n\\to\\infty}\\left(1+\\frac12+\\frac13+\\cdots+\\frac1n-\\ln n\\right)\n=0.57721\\,56649\\,01532\\,86060\\ldots.Euler's constant is the limit of the harmonic sum after subtracting its logarithmic growth. The\nsecond declaration turns the displayed decimal into a rigorous enclosure: the error is less than\none unit in its final displayed decimal place.\n\n","context":"LMLF · DLMF with Lean\u0009Gamma Function\u0009§5.2 Definitions","header":"§5.2(ii) Euler's Constant","id":"/Gamma-Function/___5___2-Definitions/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___2-Definitions--___5___2_LPAR_ii_RPAR_-Euler___s-Constant"}});